      "lt_co2_use": "Cutting metal + acrylic, surgery, marking.",
      "lt_dye": "Dye laser",
      "lt_dye_use": "Spectroscopy, research. Largely replaced by tunable solid-state.",
      "lt_dye_wl": "tunable across visible",
      "lt_excimer": "Excimer (ArF, KrF)",
      "lt_excimer_use": "LASIK eye surgery, microchip photolithography.",
      "lt_fel": "Free-electron laser (FEL)",
      "lt_fel_power": "high",
      "lt_fel_use": "Research — accelerator-based. Atomic-scale imaging.",
      "lt_fel_wl": "tunable, microwave to X-ray",
      "lt_fiber": "Fiber laser",
      "lt_fiber_use": "Industrial cutting/welding. Higher efficiency than older lasers.",
      "lt_hene": "Helium-Neon (HeNe)",
      "lt_hene_use": "Alignment, barcode scanners (old). One of the first practical lasers.",
      "lt_ndyag": "Nd:YAG",
      "lt_ndyag_use": "Industrial cutting + welding, medical (skin treatment, tattoo removal).",
      "lt_semiconductor": "Semiconductor (laser diode)",
      "lt_semiconductor_use": "CD/DVD/Blu-ray, laser pointers, fiber-optic comm.",
      "lt_tisapphire": "Ti:Sapphire",
